import React, { useEffect, useState } from 'react';
import { Grid, Paper, Typography } from '@mui/material';
import { styled } from '@mui/material/styles';
import StatCard from '../components/StatCard/StatCard';
import EmployeeChart from '../components/EmployeeChart';
import AlertList from '../components/AlertList';
import { getDashboardSummary, getEmployeeStats, getAlerts } from '../services/dashboardService';

const Item = styled(Paper)(({ theme }) => ({
    padding: theme.spacing(2),
    textAlign: 'center',
    color: theme.palette.text.secondary,
}));

function Dashboard() {
    const [summary, setSummary] = useState(null);
    const [stats, setStats] = useState(null);
    const [alerts, setAlerts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const [summaryData, statsData, alertsData] = await Promise.all([
                    getDashboardSummary(),
                    getEmployeeStats(),
                    getAlerts()
                ]);
                setSummary(summaryData);
                setStats(statsData);
                setAlerts(alertsData);
            } catch (err) {
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) return <Typography>Loading...</Typography>;
    if (error) return <Typography color="error">Error: {error}</Typography>;

    return (
        <Grid container spacing={3}>
            {/* Summary Cards */}
            <Grid item xs={12} md={4}>
                <StatCard
                    title="Growth"
                    value={`${summary?.growth || 0}%`}
                    icon="trending_up"
                    color="#1976d2"
                />
            </Grid>
            <Grid item xs={12} md={4}>
                <StatCard
                    title="New Users"
                    value={summary?.newUsers || 0}
                    icon="person_add"
                    color="#2e7d32"
                />
            </Grid>
            <Grid item xs={12} md={4}>
                <StatCard
                    title="Profit"
                    value={summary?.profit || 0}
                    icon="attach_money"
                    color="#d32f2f"
                />
            </Grid>

            {/* Charts */}
            <Grid item xs={12} md={8}>
                <Item>
                    <Typography variant="h6" gutterBottom>
                        Employee Statistics
                    </Typography>
                    <EmployeeChart data={stats?.earningStats || []} />
                </Item>
            </Grid>

            {/* Alerts */}
            <Grid item xs={12} md={4}>
                <Item>
                    <Typography variant="h6" gutterBottom>
                        Alerts
                    </Typography>
                    <AlertList alerts={alerts || []} />
                </Item>
            </Grid>
        </Grid>
    );
}

export default Dashboard;
